export const ALL_DEPARTMENTS_DISEASES: Disease[] = diseaseSeeds.map(disease);

function term(seed: TermRow): MedicalTerm {
  return T({
    ...seed,
    ex: seed.ex ?? {
      japanese: `${seed.ja}を確認します。`,
      kana: `${seed.kana}をかくにんします。`,
      indonesian: `Kami akan menilai ${seed.idn}.`,
      english: `We will assess ${seed.en}.`,
    },
  });
}

