export const ALL_DEPARTMENTS_TERMS: MedicalTerm[] = termSeeds.map(term);

type InvestigationSeed = {
  id: string;
  japanese: string;
  kana: string;
  indonesian: string;
  english: string;
  category: Investigation['category'];
  specialties: string[];
  purposeJa: string;
  purposeKana: string;
  purposeIndonesian: string;
  purposeEnglish: string;
  prep?: [string, string, string, string];
  relatedDiseases: string[];
  relatedTerms: string[];
};

function investigation(seed: InvestigationSeed): Investigation {
  return I({
    id: seed.id,
    japanese: seed.japanese,
    kana: seed.kana,
    indonesian: seed.indonesian,
    english: seed.english,
    category: seed.category,
    specialties: seed.specialties,
    relatedDiseases: seed.relatedDiseases,
    relatedTerms: seed.relatedTerms,
    patientExplanation: line(
      `${seed.japanese}で${seed.purposeJa}を確認します。`,
      `${seed.kana}で${seed.purposeKana}をかくにんします。`,
      seed.purposeIndonesian,
      seed.purposeEnglish,
    ),
    preparationInstruction: seed.prep ? line(...seed.prep) : undefined,
    resultDiscussion: line(
      '結果を確認して、次の方針をご説明します。',
      'けっかをかくにんして、つぎのほうしんをごせつめいします。',
      'Kami akan meninjau hasilnya dan menjelaskan langkah selanjutnya.',
      'We will review the result and explain the next steps.',
    ),
    verificationStatus: 'reviewed',
    junitPriority: 'common',
  });
}

